import{_ as t,o as l,c as e,a2 as i}from"./chunks/framework.DaAAbehN.js";const c=JSON.parse('{"title":"第 16 课：下一步可以学什么","description":"","frontmatter":{},"headers":[],"relativePath":"modules/module-6/lesson-16.md","filePath":"modules/module-6/lesson-16.md"}'),o={name:"modules/module-6/lesson-16.md"};function r(s,a,d,n,h,p){return l(),e("div",null,[...a[0]||(a[0]=[i(`<h1 id="第-16-课-下一步可以学什么" tabindex="-1">第 16 课：下一步可以学什么 <a class="header-anchor" href="#第-16-课-下一步可以学什么" aria-label="Permalink to &quot;第 16 课：下一步可以学什么&quot;">​</a></h1><blockquote><p>📌 <strong>学习目标</strong>：了解 Codex 进阶学习方向，规划后续学习路径<br> ⏱️ <strong>预计时长</strong>：15 分钟<br> 🎯 <strong>本节节奏</strong>：介绍 + 引导</p></blockquote><hr><h2 id="一、你已经学会了什么" tabindex="-1">一、你已经学会了什么？ <a class="header-anchor" href="#一、你已经学会了什么" aria-label="Permalink to &quot;一、你已经学会了什么？&quot;">​</a></h2><p>完成这门课程后，你应该能够：</p><ul><li>✅ 理解 Codex 是什么、能做什么</li><li>✅ 安装和登录 Codex 桌面 App</li><li>✅ 使用自然语言指挥 Codex 完成文件操作</li><li>✅ 让 Codex 联网搜索并整理资料</li><li>✅ 使用 Codex 技能快速完成复杂任务</li><li>✅ 独立完成从需求到交付的完整项目</li></ul><hr><h2 id="二、进阶学习方向" tabindex="-1">二、进阶学习方向 <a class="header-anchor" href="#二、进阶学习方向" aria-label="Permalink to &quot;二、进阶学习方向&quot;">​</a></h2><h3 id="方向-1-cli-命令行版本" tabindex="-1">方向 1：CLI 命令行版本 <a class="header-anchor" href="#方向-1-cli-命令行版本" aria-label="Permalink to &quot;方向 1：CLI 命令行版本&quot;">​</a></h3><p>如果你已经熟悉桌面 App，可以尝试命令行版本。</p><p><strong>适合人群</strong>：想更灵活地控制 Codex 的用户</p><p><strong>学习内容</strong>：</p><ul><li>安装 Codex CLI</li><li>使用命令行参数指定工作区和指令</li><li>编写脚本自动化调用 Codex</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 示例命令</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --workspace</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./my-project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;帮我重构这个项目的代码&quot;</span></span></code></pre></div><h3 id="方向-2-自定义技能" tabindex="-1">方向 2：自定义技能 <a class="header-anchor" href="#方向-2-自定义技能" aria-label="Permalink to &quot;方向 2：自定义技能&quot;">​</a></h3><p>把常用的工作流固化为可复用的技能模板。</p><p><strong>适合人群</strong>：有固定重复性工作的用户</p><p><strong>学习内容</strong>：</p><ul><li>分析自己的高频工作场景</li><li>设计技能模板的结构</li><li>用 Codex 生成技能配置文件</li><li>测试和优化技能效果</li></ul><h3 id="方向-3-mcp-扩展" tabindex="-1">方向 3：MCP 扩展 <a class="header-anchor" href="#方向-3-mcp-扩展" aria-label="Permalink to &quot;方向 3：MCP 扩展&quot;">​</a></h3><p>MCP（Model Context Protocol）是连接外部工具和数据源的协议。</p><p><strong>适合人群</strong>：想将 Codex 与更多工具集成的用户</p><p><strong>学习内容</strong>：</p><ul><li>了解 MCP 的基本概念</li><li>配置 MCP 服务器连接外部 API</li><li>使用 MCP 扩展 Codex 的能力</li></ul><h3 id="方向-4-多智能体协作" tabindex="-1">方向 4：多智能体协作 <a class="header-anchor" href="#方向-4-多智能体协作" aria-label="Permalink to &quot;方向 4：多智能体协作&quot;">​</a></h3><p>同时让多个 AI 智能体做不同的事。</p><p><strong>适合人群</strong>：处理复杂项目的用户</p><p><strong>学习内容</strong>：</p><ul><li>设计多智能体协作流程</li><li>分配不同任务给不同的智能体</li><li>整合各智能体的输出结果</li></ul><hr><h2 id="三、实践建议" tabindex="-1">三、实践建议 <a class="header-anchor" href="#三、实践建议" aria-label="Permalink to &quot;三、实践建议&quot;">​</a></h2><h3 id="每天练一点" tabindex="-1">每天练一点 <a class="header-anchor" href="#每天练一点" aria-label="Permalink to &quot;每天练一点&quot;">​</a></h3><ul><li>每天花 10-15 分钟用 Codex 完成一个小任务</li><li>记录每次使用的指令和结果</li><li>逐步积累自己的&quot;指令库&quot;</li></ul><h3 id="加入社区" tabindex="-1">加入社区 <a class="header-anchor" href="#加入社区" aria-label="Permalink to &quot;加入社区&quot;">​</a></h3><ul><li>加入 Codex/ChatGPT 用户社区</li><li>分享你的使用经验和技巧</li><li>学习别人的创意用法</li></ul><h3 id="持续学习" tabindex="-1">持续学习 <a class="header-anchor" href="#持续学习" aria-label="Permalink to &quot;持续学习&quot;">​</a></h3><ul><li>关注 OpenAI 的官方更新</li><li>尝试新功能和新技能</li><li>探索新的应用场景</li></ul><hr><h2 id="四、本节小结" tabindex="-1">四、本节小结 <a class="header-anchor" href="#四、本节小结" aria-label="Permalink to &quot;四、本节小结&quot;">​</a></h2><table tabindex="0"><thead><tr><th>学习方向</th><th>适合人群</th><th>核心价值</th></tr></thead><tbody><tr><td>CLI 命令行</td><td>进阶用户</td><td>更灵活的自动化控制</td></tr><tr><td>自定义技能</td><td>有固定工作流的用戶</td><td>提高效率，减少重复劳动</td></tr><tr><td>MCP 扩展</td><td>技术爱好者</td><td>连接更多外部工具</td></tr><tr><td>多智能体协作</td><td>复杂项目处理者</td><td>并行处理，提高效率</td></tr></tbody></table><hr><h2 id="五、结语" tabindex="-1">五、结语 <a class="header-anchor" href="#五、结语" aria-label="Permalink to &quot;五、结语&quot;">​</a></h2><p>恭喜你完成了这门课程！</p><p>记住，Codex 只是一个工具，真正有价值的是你用它解决了什么问题。不要害怕犯错，每一次&quot;不对&quot;都是学习的机会。</p><p><strong>最重要的是——开始用起来吧！</strong></p><hr><h2 id="六、反馈与改进" tabindex="-1">六、反馈与改进 <a class="header-anchor" href="#六、反馈与改进" aria-label="Permalink to &quot;六、反馈与改进&quot;">​</a></h2><p>如果你觉得这门课程对你有帮助，或者有任何改进建议，欢迎填写 <a href="./../../appendix/feedback.html">课后反馈表</a>。</p>`,48)])])}const b=t(o,[["render",r]]);export{c as __pageData,b as default};
